using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Underwater.Editor {
public static class MantaFixedCephalicPose {
 public static void Run(){
 var scene=EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");var manta=GameObject.Find("Manta ray gliding over the reef");var player=manta.GetComponentInChildren<Animation>();var original=player.clip;var clip=UnityEngine.Object.Instantiate(original);clip.name="Manta swim with fixed curled face fins";int count=0;
 foreach(var binding in AnimationUtility.GetCurveBindings(clip)){if(binding.propertyName.StartsWith("blendShape.")&&(binding.propertyName.Contains("cephalic_fin")||binding.propertyName.Contains("jaw."))){AnimationUtility.SetEditorCurve(clip,binding,AnimationCurve.Constant(0,clip.length,0));count++;continue;}if(!binding.path.Contains("cephalic_fin")&&!binding.path.Contains("/head.")&&!binding.path.Contains("/jaw."))continue;var bone=AnimationUtility.GetAnimatedObject(player.gameObject,binding) as Transform;if(!bone)throw new Exception("Missing cephalic bone");var property=new SerializedObject(bone).FindProperty(binding.propertyName);if(property==null)throw new Exception("Unknown face curve "+binding.propertyName);float value=property.floatValue;AnimationUtility.SetEditorCurve(clip,binding,AnimationCurve.Constant(0,clip.length,value));count++;}
 if(count<24)throw new Exception("Missing face-fin animation curves");const string folder="Assets/UnderwaterArt/PreparedMarine/MantaRay/";string path=folder+"MantaFixedFace.anim";var saved=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(saved){EditorUtility.CopySerialized(clip,saved);UnityEngine.Object.DestroyImmediate(clip);}else{saved=clip;AssetDatabase.CreateAsset(saved,path);}foreach(AnimationState state in player.Cast<AnimationState>().ToArray())player.RemoveClip(state.name);player.AddClip(saved,saved.name);player.clip=saved;EditorUtility.SetDirty(player);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);
 var fins=player.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("cephalic_fin")).ToArray();var rotations=fins.Select(t=>t.localRotation).ToArray();var wing=player.GetComponentsInChildren<Transform>().First(t=>t.name=="pectoral.L.006");var wingStart=wing.localRotation;float maxFace=0,maxWing=0;
 for(int i=0;i<80;i++){saved.SampleAnimation(player.gameObject,saved.length*i/80);for(int j=0;j<fins.Length;j++)maxFace=Mathf.Max(maxFace,Quaternion.Angle(rotations[j],fins[j].localRotation));maxWing=Mathf.Max(maxWing,Quaternion.Angle(wingStart,wing.localRotation));}if(maxFace>.05f||maxWing<2)throw new Exception("Face lock/wing motion failed: "+maxFace+" / "+maxWing);
 Directory.CreateDirectory("Renders/MantaFixedFace");File.WriteAllText("Renders/MantaFixedFace/Validation.txt","Active skeletal manta: "+count+" cephalic-fin curves fixed to authored curled pose. Maximum face-joint rotation="+maxFace+" degrees; wing rotation="+maxWing+" degrees across 80 clip samples.\n");
 var cam=Camera.main;var optics=cam.GetComponent<ReefOptics>();if(optics)optics.enabled=false;cam.fieldOfView=42;cam.transform.position=manta.transform.TransformPoint(new Vector3(0,-1.6f,3.5f));cam.transform.LookAt(manta.transform.TransformPoint(new Vector3(0,.15f,1.3f)),manta.transform.up);var skin=player.GetComponentInChildren<SkinnedMeshRenderer>();for(int i=0;i<2;i++){saved.SampleAnimation(player.gameObject,saved.length*i*.5f);DolphinMotionIntegration.CapturePosed(cam,skin,"Renders/MantaFixedFace/ActiveFace"+i+".png");}Debug.Log("MANTA_ACTIVE_FACE_FIXED");EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");
 }
}
}
